import pytest
from marshmallow import Schema, fields, ValidationError

def test_constant_field_required():
    class MySchema(Schema):
        foo = fields.Constant("bar", required=True)

    schema = MySchema()
    # Should not raise ValueError during init
    # When serialized, should serialize to constant
    assert schema.dump({}) == {"foo": "bar"}
    # When deserialized, should deserialize to constant even if missing or provided
    assert schema.load({}) == {"foo": "bar"}
    assert schema.load({"foo": "anything"}) == {"foo": "bar"}

